import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('createCreditNote creates credit note for issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const credit = createCreditNote(issued.value, { amount: 100000, reason: 'Discount', date: '2026-10-15' }, []);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.number, 'CN-2026-0001');
  assert.equal(credit.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(credit.value.customerId, 'C-001');
  assert.equal(credit.value.amount, 100000);
  assert.equal(credit.value.reason, 'Discount');
  assert.equal(credit.value.date, '2026-10-15');
});

test('createCreditNote rejects draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const credit = createCreditNote(invoice.value, { amount: 100000, reason: 'Discount', date: '2026-10-15' }, []);
  assert.deepEqual(credit, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote accepts partially_paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const payment = recordPayment(issued.value, { amount: 500000, date: '2026-10-15' });
  const credit = createCreditNote(payment.value, { amount: 100000, reason: 'Discount', date: '2026-10-20' }, []);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.status, 'partially_paid');
});

test('createCreditNote accepts paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const payment = recordPayment(issued.value, { amount: 1034550, date: '2026-10-15' });
  const credit = createCreditNote(payment.value, { amount: 100000, reason: 'Adjustment', date: '2026-10-20' }, []);
  assert.equal(credit.ok, true);
});

test('createCreditNote rejects invalid amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const credit = createCreditNote(issued.value, { amount: 0, reason: 'Discount', date: '2026-10-15' }, []);
  assert.deepEqual(credit, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const credit = createCreditNote(issued.value, { amount: -100000, reason: 'Discount', date: '2026-10-15' }, []);
  assert.deepEqual(credit, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects fractional amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const credit = createCreditNote(issued.value, { amount: 100000.5, reason: 'Discount', date: '2026-10-15' }, []);
  assert.deepEqual(credit, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects credit too high', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // Invoice total is 1034550
  const credit = createCreditNote(issued.value, { amount: 1034551, reason: 'Discount', date: '2026-10-15' }, []);
  assert.deepEqual(credit, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote accepts amount equal to invoice total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  // Invoice total is 1034550
  const credit = createCreditNote(issued.value, { amount: 1034550, reason: 'Full refund', date: '2026-10-15' }, []);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.amount, 1034550);
});

test('createCreditNote numbers correctly with existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const existing = ['INV-2026-0001', 'CN-2026-0001', 'CN-2026-0002'];
  const credit = createCreditNote(issued.value, { amount: 100000, reason: 'Discount', date: '2026-10-15' }, existing);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.number, 'CN-2026-0003');
});

test('createCreditNote uses separate counters for invoice and credit notes', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, ['INV-2026-0001', 'INV-2026-0002']);
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const credit = createCreditNote(issued.value, { amount: 100000, reason: 'Discount', date: '2026-10-15' }, existing);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.number, 'CN-2026-0001');
});

test('createCreditNote handles multiple years', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const existing = ['CN-2026-0005'];
  const credit = createCreditNote(issued.value, { amount: 100000, reason: 'Discount', date: '2027-01-20' }, existing);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.number, 'CN-2027-0001');
});

test('createCreditNote includes all invoice details', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 50 }],
  });
  const issued = issueInvoice(invoice.value, ['INV-2026-0001']);
  const credit = createCreditNote(issued.value, { amount: 50000, reason: 'Quantity adjustment', date: '2026-10-20' }, []);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.invoiceNumber, 'INV-2026-0002');
  assert.equal(credit.value.customerId, 'C-003');
  assert.equal(credit.value.reason, 'Quantity adjustment');
});

test('createCreditNote reason can be any string', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const credit = createCreditNote(issued.value, { amount: 100000, reason: 'Customer complaint - service not rendered', date: '2026-10-15' }, []);
  assert.equal(credit.ok, true);
  assert.equal(credit.value.reason, 'Customer complaint - service not rendered');
});

